// ===== Part B: glossary =====
FGLOSS["startup"]=G('problem validation=التحقق من المشكلة|customer discovery=اكتشاف العملاء|MVP=المنتج الأدنى القابل للتجربة|product-market fit=ملاءمة المنتج للسوق|pitch deck=عرض المستثمرين|investor update=تحديث المستثمرين|burn rate=معدل الحرق|runway=المدة المتبقية بالكاش|unit economics=اقتصاديات الوحدة|CAC=تكلفة اكتساب العميل|LTV=القيمة الدائمة للعميل|gross margin=هامش الربح الإجمالي|churn=معدل فقد العملاء|MRR=الإيراد الشهري المتكرر|cap table=جدول الملكية|dilution=تخفيف الملكية|term sheet=ورقة الشروط|go-to-market=خطة دخول السوق|ICP=ملف العميل المثالي|vesting=استحقاق الأسهم التدريجي');
FGLOSS["education"]=G('learning objective=هدف التعلم|lesson plan=خطة الدرس|scheme of work=توزيع المنهج|differentiation=التعليم المتمايز|scaffolding=الدعم التدريجي|formative assessment=التقييم التكويني|summative assessment=التقييم الختامي|rubric=سلم التقدير|exit ticket=تذكرة الخروج|success criteria=معايير النجاح|learning outcome=ناتج التعلم|Bloom taxonomy=تصنيف بلوم|item analysis=تحليل الأسئلة|re-teaching=إعادة الشرح|academic integrity=النزاهة الأكاديمية|plagiarism=الانتحال|SEN=ذوي الاحتياجات التعليمية الخاصة|parent conference=اجتماع أولياء الأمور|curriculum standard=معيار المنهج|moderation=توحيد التصحيح');

